export function regulations(c: CustomerProfile, tenantId = 'all'): Reg[] {
  const fx = fxFromUsd(c.currency);
  const size = Math.max(0.6, Math.min(2.4, Math.log10(c.employees) - 2.6));
  const out = forCustomer(S, c).map((s, i) => {
    const r = rng(`hz-${c.id}-${s.id}`);
    const fwShorts = s.fw.map((id) => ({ id, short: c.frameworks.find((f) => f.id === id)?.short ?? id.toUpperCase() })).filter((f) => c.frameworks.some((x) => x.id === f.id));
    const controls = Math.round((r.int(8, 22) + s.themes.length * 3) * s.weight);
    const readiness = s.months < 0 ? r.int(68, 88) : s.stage === 'Consultation' || s.stage === 'Guidance' ? r.int(30, 62) : r.int(42, 78);
    const gaps = Math.max(1, Math.round(controls * (1 - readiness / 100)));
    const effortDays = Math.round(gaps * r.int(4, 9) * size);
    const cost = Math.round((effortDays * 1150 + gaps * r.int(6, 22) * 1000 * s.weight) * fx / 1000) * 1000;
    const p = c.people[s.owner] ?? c.people.ciso;
    const feedStatus: FeedStatus = !s.update ? 'assessed' : s.update.daysAgo <= 9 ? 'new' : r.chance(0.3) ? 'not applicable' : r.chance(0.5) ? 'actions raised' : 'assessed';
    return {
      ...s, owner: { name: p.name, role: p.role }, controls, gaps, effortDays, cost, readiness, fwShorts,
      tenantNames: s.tenants === 'all' ? ['Group-wide'] : s.tenants.map((t) => c.tenants.find((x) => x.id === t)?.short ?? t),
      feedStatus: feedStatus === 'not applicable' && i < 2 ? 'assessed' : feedStatus, raised: feedStatus === 'actions raised' ? Math.min(gaps, r.int(2, 6)) : 0,
    } as Reg;
  });
  if (tenantId === 'all') return out.sort((a, b) => a.months - b.months);
  return out.filter((x) => x.tenants === 'all' || x.tenants.includes(tenantId)).sort((a, b) => a.months - b.months);
}

export function horizonTotals(regs: Reg[]) {
  const next12 = regs.filter((r) => r.months >= 0 && r.months <= 12);
  return {
    tracked: regs.length,
    next12: next12.length,
    applying: regs.filter((r) => r.months < 0).length,
    gaps: regs.reduce((s, r) => s + r.gaps, 0),
    cost12: next12.reduce((s, r) => s + r.cost, 0) + regs.filter((r) => r.months < 0).reduce((s, r) => s + r.cost, 0),
    readiness: Math.round(regs.reduce((s, r) => s + r.readiness * r.controls, 0) / Math.max(1, regs.reduce((s, r) => s + r.controls, 0))),
    toAssess: regs.filter((r) => r.update && r.feedStatus === 'new').length,
    effort: regs.reduce((s, r) => s + r.effortDays, 0),
  };
}

/** Spend profile: cost of closing each regulation's gaps, spread over the quarters before it applies. */
export function costByQuarter(regs: Reg[]): { label: string; byJur: Record<Jurisdiction, number> }[] {
  const now = new Date();
  const qs: { label: string; byJur: Record<Jurisdiction, number> }[] = [];
  for (let q = 0; q < 4; q++) {
    const d = new Date(now.getFullYear(), now.getMonth() + q * 3, 1);
    qs.push({ label: `Q${Math.floor(d.getMonth() / 3) + 1} ${String(d.getFullYear()).slice(2)}`, byJur: Object.fromEntries(JURISDICTIONS.map((j) => [j, 0])) as Record<Jurisdiction, number> });
  }
  for (const r of regs) {
    if (r.months > 12) continue;
    // Remediation runs from now until about two quarters after the obligation applies.
    const span = Math.max(2, Math.min(4, Math.ceil((Math.max(r.months, 0) + 6) / 3)));
    for (let q = 0; q < span; q++) qs[q].byJur[r.jur] += r.cost / span;
  }
  return qs;
}

